@router.delete("/{job_id}", status_code=204)
def cancel_job(
    job_id: str,
    request: Request,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    """Cancel a job (soft - sets status). Only dispatchers/admins."""
    job = db.query(models.Job).filter(models.Job.id == job_id).one_or_none()
    if not job:
        raise HTTPException(status_code=404, detail="Not found")
    if user.role not in (models.UserRole.ops_admin, models.UserRole.dispatcher):
        raise HTTPException(status_code=403, detail="Forbidden")
    if user.role == models.UserRole.dispatcher:
        assert_dispatcher_can_access_region(db, user, job.region_id)
    if models.JobStatus.cancelled not in models.JOB_STATUS_TRANSITIONS.get(job.status, set()):
        raise HTTPException(status_code=400, detail=f"Cannot cancel job in status {job.status.value}")
    old = job.status
    job.status = models.JobStatus.cancelled
    db.add(job)
    write_audit(db, actor=user, action="job.cancel", target_type="job", target_id=job.id, details={"from": old.value}, ip_address=get_client_ip(request))
    db.commit()
    enqueue_event(db, "job.cancelled", {"job_id": job.id, "code": job.code})
    return None


