@router.post("/password-reset/confirm", status_code=204)
def confirm_password_reset(
    payload: schemas.PasswordResetConfirm,
    request: Request,
    db: Session = Depends(get_db),
):
    token_hash = hash_token(payload.token)
    token = db.query(models.PasswordResetToken).filter(models.PasswordResetToken.token_hash == token_hash).one_or_none()
    if not token or token.used_at is not None:
        raise HTTPException(status_code=400, detail="Invalid or expired token")
    expires = token.expires_at
    if expires.tzinfo is None:
        expires = expires.replace(tzinfo=timezone.utc)
    if expires < datetime.now(timezone.utc):
        raise HTTPException(status_code=400, detail="Invalid or expired token")
    user = db.query(models.User).filter(models.User.id == token.user_id).one_or_none()
    if not user or not user.is_active:
        raise HTTPException(status_code=400, detail="Invalid or expired token")
    user.password_hash = hash_password(payload.new_password)
    token.used_at = datetime.now(timezone.utc)
    # Kill existing sessions
    db.query(models.Session).filter(models.Session.user_id == user.id).delete()
    write_audit(db, actor=user, action="user.password_reset.confirmed", target_type="user", target_id=user.id, ip_address=get_client_ip(request))
    db.commit()
    return Response(status_code=204)

@router.put("/{user_id}", response_model=schemas.UserPublic)
def update_user(
    user_id: str,
    payload: schemas.UserUpdate,
    request: Request,
    db: Session = Depends(get_db),
    actor: models.User = Depends(require_roles(models.UserRole.ops_admin)),
):
    user = db.query(models.User).filter(models.User.id == user_id).one_or_none()
    if not user:
        raise HTTPException(status_code=404, detail="Not found")
    # Prevent admin from deactivating themselves
    if user.id == actor.id and payload.is_active is False:
        raise HTTPException(status_code=400, detail="Cannot deactivate yourself")
    changes: dict = {}
    if payload.full_name is not None:
        changes["full_name"] = {"from": user.full_name, "to": payload.full_name}
        user.full_name = payload.full_name.strip()
    if payload.phone is not None:
        user.phone = payload.phone
    if payload.role is not None and payload.role != user.role:
        if user.id == actor.id:
            raise HTTPException(status_code=400, detail="Cannot change your own role")
        changes["role"] = {"from": user.role.value, "to": payload.role.value}
        user.role = payload.role
    if payload.is_active is not None and payload.is_active != user.is_active:
        changes["is_active"] = {"from": user.is_active, "to": payload.is_active}
        user.is_active = payload.is_active
        if not payload.is_active:
            db.query(models.Session).filter(models.Session.user_id == user.id).delete()
    if payload.new_password:
        try:
            user.password_hash = hash_password(payload.new_password)
        except ValueError as e:
            raise HTTPException(status_code=400, detail=str(e))
        db.query(models.Session).filter(models.Session.user_id == user.id).delete()
        changes["password"] = "reset"
    db.add(user)
    write_audit(db, actor=actor, action="admin.user.update", target_type="user", target_id=user.id,
                details=changes, ip_address=get_client_ip(request))
    db.commit()

@router.post("/{job_id}/status")
def change_status(
    job_id: str,
    payload: schemas.JobStatusChange,
    request: Request,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    job = db.query(models.Job).filter(models.Job.id == job_id).one_or_none()
    if not job:
        raise HTTPException(status_code=404, detail="Not found")
    if not user_can_modify_job(db, user, job):
        raise HTTPException(status_code=403, detail="Forbidden")

    # Field workers can only do operational transitions, not cancel
    new_status = payload.status
    if user.role == models.UserRole.field_worker and new_status == models.JobStatus.cancelled:
        raise HTTPException(status_code=403, detail="Workers cannot cancel jobs")
    if user.role == models.UserRole.field_worker and new_status == models.JobStatus.assigned:
        raise HTTPException(status_code=403, detail="Workers cannot reassign jobs")

    allowed = models.JOB_STATUS_TRANSITIONS.get(job.status, set())
    if new_status not in allowed:
        raise HTTPException(status_code=400, detail=f"Invalid transition from {job.status.value} to {new_status.value}")

    # Completion requires proof when service type requires it
    if new_status == models.JobStatus.completed:
        if job.service_type and job.service_type.requires_proof:
            has_proof = db.query(models.Proof).filter(models.Proof.job_id == job.id).first()
            if not has_proof:
                raise HTTPException(status_code=400, detail="Proof is required to complete this job")

    old = job.status
    job.status = new_status
    now = datetime.now(timezone.utc)
    if new_status == models.JobStatus.in_progress and not job.started_at:
        job.started_at = now
    if new_status == models.JobStatus.completed:
        job.completed_at = now
    if new_status == models.JobStatus.failed:
        job.failure_reason = payload.failure_reason or "Failed"

    db.add(job)
    write_audit(db, actor=user, action="job.status_change", target_type="job", target_id=job.id,
                details={"from": old.value, "to": new_status.value}, ip_address=get_client_ip(request))

    # Notify customer for some statuses
    customer = job.customer
    if customer and customer.user_id and new_status in (models.JobStatus.en_route, models.JobStatus.arrived, models.JobStatus.completed, models.JobStatus.cancelled, models.JobStatus.failed):
        notify(db, user_id=customer.user_id, title=f"Job {job.code} is now {new_status.value}", link=f"/portal/jobs/{job.id}")
    db.commit()
    db.refresh(job)
    enqueue_event(db, "job.status_changed", {"job_id": job.id, "code": job.code, "from": old.value, "to": new_status.value})
    return _serialize_job(job, requester=user)

def hash_token(token: str) -> str:
    """Hash a token with HMAC-SHA256 using the app secret as the key.
    Tokens are random and high-entropy, so HMAC-SHA256 is sufficient and constant-time.
    """
    return hmac.new(settings.secret_key.encode("utf-8"), token.encode("utf-8"), hashlib.sha256).hexdigest()

@router.post("/{job_id}/assign")
def assign_job(
    job_id: str,
    payload: schemas.JobAssign,
    request: Request,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    job = db.query(models.Job).filter(models.Job.id == job_id).one_or_none()
    if not job:
        raise HTTPException(status_code=404, detail="Not found")
    if user.role not in (models.UserRole.ops_admin, models.UserRole.dispatcher):
        raise HTTPException(status_code=403, detail="Forbidden")
    if user.role == models.UserRole.dispatcher:
        assert_dispatcher_can_access_region(db, user, job.region_id)
    if job.status in (models.JobStatus.completed, models.JobStatus.cancelled):
        raise HTTPException(status_code=400, detail="Cannot reassign a closed job")

    old_worker_id = job.assigned_worker_id
    if payload.worker_id is None:
        job.assigned_worker_id = None
        if job.status in (models.JobStatus.assigned, models.JobStatus.en_route, models.JobStatus.arrived):
            job.status = models.JobStatus.unassigned
    else:
        worker = db.query(models.Worker).filter(models.Worker.id == payload.worker_id).one_or_none()
        if not worker:
            raise HTTPException(status_code=400, detail="Invalid worker")
        if worker.region_id and worker.region_id != job.region_id:
            raise HTTPException(status_code=400, detail="Worker not in this region")
        job.assigned_worker_id = worker.id
        if job.status == models.JobStatus.unassigned or job.status == models.JobStatus.failed:
            job.status = models.JobStatus.assigned
    db.add(job)
    write_audit(db, actor=user, action="job.assign", target_type="job", target_id=job.id,
                details={"from": old_worker_id, "to": job.assigned_worker_id}, ip_address=get_client_ip(request))
    if job.assigned_worker_id and job.assigned_worker and job.assigned_worker.user_id:
        notify(db, user_id=job.assigned_worker.user_id, title=f"Job assigned to you: {job.code}", link=f"/worker/jobs/{job.id}")
    db.commit()
    db.refresh(job)
    enqueue_event(db, "job.assigned", {"job_id": job.id, "code": job.code, "worker_id": job.assigned_worker_id})
    return _serialize_job(job, requester=user)

